export function bulletHoleTexture() {
  if (TEX_CACHE.has('hole')) return TEX_CACHE.get('hole');
  const c = canvas(64);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(32, 32, 2, 32, 32, 30);
  g.addColorStop(0, 'rgba(5,6,7,0.95)');
  g.addColorStop(0.32, 'rgba(12,14,16,0.8)');
  g.addColorStop(0.55, 'rgba(40,44,48,0.35)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  // crack rays
  ctx.strokeStyle = 'rgba(100,105,110,0.24)';
  for (let i = 0; i < 8; i++) {
    const a = rnd(0, Math.PI * 2);
    ctx.lineWidth = rnd(0.5, 1.4);
    ctx.beginPath();
    ctx.moveTo(32 + Math.cos(a) * 5, 32 + Math.sin(a) * 5);
    ctx.lineTo(32 + Math.cos(a) * rnd(12, 28), 32 + Math.sin(a) * rnd(12, 28));
    ctx.stroke();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  TEX_CACHE.set('hole', t);
  return t;
}

export function screenNoiseTexture() {
  const c = canvas(256);
  const ctx = c.getContext('2d');
  const img = ctx.createImageData(256, 256);
  for (let i = 0; i < img.data.length; i += 4) {
    const v = Math.random() * 255;
    img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
    img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(4, 4);
  return t;
}

export function windowTexture(seed = 0) {
  const key = `windows-${seed}`;
  if (TEX_CACHE.has(key)) return TEX_CACHE.get(key);
  const c = canvas(256);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#070a0e';
  ctx.fillRect(0, 0, 256, 256);
  const cols = 16, rows = 24;
  const colors = ['rgba(210,160,80,', 'rgba(120,180,190,', 'rgba(155,170,185,'];
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      if (Math.random() < 0.24) {
        const col = colors[Math.floor(Math.random() * colors.length)];
        ctx.fillStyle = col + rnd(0.25, 0.9) + ')';
        ctx.fillRect(4 + x * 15.5, 4 + y * 10.3, rnd(3, 9), 3);
      }
    }
  }
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  TEX_CACHE.set(key, t);
  return t;
}

// Fully procedural audio: no external samples.
export class GameAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.ambientGain = null;
    this.noise = null;
    this.started = false;
    this.volume = 0.8;
    this.heartbeatTimer = 0;
    this.tension = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    const ctx = this.ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.volume;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 18;
    comp.ratio.value = 4;
    comp.attack.value = 0.003;
    comp.release.value = 0.25;
    this.master.connect(comp);
    comp.connect(ctx.destination);
    this.sfxGain = ctx.createGain();
    this.sfxGain.gain.value = 0.85;
    this.sfxGain.connect(this.master);
    this.ambientGain = ctx.createGain();
    this.ambientGain.gain.value = 0.5;
    this.ambientGain.connect(this.master);
    this.musicGain = ctx.createGain();
    this.musicGain.gain.value = 0.38;
    this.musicGain.connect(this.master);
    this.noise = this.makeNoise(2.4);
    this.startAmbience();
    this.started = true;
  }

  makeNoise(seconds = 2) {
    const ctx = this.ctx;
    const buffer = ctx.createBuffer(2, Math.floor(ctx.sampleRate * seconds), ctx.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const data = buffer.getChannelData(ch);
      let last = 0;
      for (let i = 0; i < data.length; i++) {
        const white = Math.random() * 2 - 1;
        last = (last + 0.02 * white) / 1.02;
        data[i] = last * 3.2 + white * 0.32;
      }
    }
    return buffer;
  }

  noiseSource(duration, loop = false) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = loop;
    if (!loop) src.start(this.ctx.currentTime, Math.random() * 1.5, duration);
    return src;
  }

  env(node, peak, attack, decay, when = 0) {
    const t = this.ctx.currentTime + when;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(peak, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + attack + decay);
    node.connect(g);
    return g;
  }

  tone({ type = 'sine', freq = 220, endFreq = null, dur = 0.2, gain = 0.2, when = 0, dest = null, slide = 0.25 }) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + when;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + dur * slide + 0.01);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.004);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g);
    g.connect(dest || this.sfxGain);
    osc.start(t);
    osc.stop(t + dur + 0.05);
  }

  burst({ dur = 0.2, gain = 0.2, freq = 800, q = 0.8, type = 'lowpass', when = 0, dest = null, sweep = true }) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + when;
    const src = this.noiseSource(dur + 0.1);
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t);
    filter.Q.value = q;
    if (sweep) filter.frequency.exponentialRampToValueAtTime(Math.max(60, freq * 0.25), t + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.004);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(dest || this.sfxGain);
    src.start(t, Math.random() * 1.2, dur + 0.1);
    src.stop(t + dur + 0.1);
  }

  startAmbience() {
    const ctx = this.ctx;
    // Rain bed
    const rain = this.noiseSource(2.4, true);
    const rainHp = ctx.createBiquadFilter();
    rainHp.type = 'highpass';
    rainHp.frequency.value = 900;
    const rainLp = ctx.createBiquadFilter();
    rainLp.type = 'lowpass';
    rainLp.frequency.value = 6200;
    const rainGain = ctx.createGain();
    rainGain.gain.value = 0.075;
    rain.connect(rainHp); rainHp.connect(rainLp); rainLp.connect(rainGain); rainGain.connect(this.ambientGain);
    rain.start();
    // Wind
    const wind = this.noiseSource(2.4, true);
    const windLp = ctx.createBiquadFilter();
    windLp.type = 'lowpass';
    windLp.frequency.value = 260;
    const windGain = ctx.createGain();
    windGain.gain.value = 0.16;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.08;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 0.09;
    lfo.connect(lfoGain); lfoGain.connect(windGain.gain);
    wind.connect(windLp); windLp.connect(windGain); windGain.connect(this.ambientGain);
    wind.start(); lfo.start();
    // Low facility drone
    const droneGain = ctx.createGain();
    droneGain.gain.value = 0.045;
    droneGain.connect(this.ambientGain);
    [41.2, 55, 82.4].forEach((f, i) => {
      const o = ctx.createOscillator();
      o.type = i === 2 ? 'triangle' : 'sine';
      o.frequency.value = f;
      o.detune.value = i * 4 - 5;
      const g = ctx.createGain();
      g.gain.value = i === 2 ? 0.22 : 0.6;
      o.connect(g); g.connect(droneGain);
      o.start();
    });
    // distant electrical hum
    const hum = ctx.createOscillator();
    hum.type = 'sawtooth';
    hum.frequency.value = 120;
    const humLp = ctx.createBiquadFilter();
    humLp.type = 'lowpass';
    humLp.frequency.value = 240;
    const humGain = ctx.createGain();
    humGain.gain.value = 0.006;
    hum.connect(humLp); humLp.connect(humGain); humGain.connect(this.ambientGain);
    hum.start();
  }

  setVolume(v) {
    this.volume = v;
    if (this.master) this.master.gain.setTargetAtTime(v, this.ctx.currentTime, 0.05);
  }

  setTension(v) {
    if (!this.ctx) return;
    this.tension = v;
    if (this.musicGain) this.musicGain.gain.setTargetAtTime(0.28 + v * 0.32, this.ctx.currentTime, 0.5);
  }

  shot(kind = 'rifle') {
    if (!this.ctx) return;
    if (kind === 'rifle') {
      this.burst({ dur: 0.16, gain: 0.5, freq: 3400, q: 0.7, type: 'highpass' });
      this.burst({ dur: 0.11, gain: 0.34, freq: 1200, q: 1.1, type: 'bandpass' });
      this.tone({ type: 'triangle', freq: 150, endFreq: 48, dur: 0.16, gain: 0.55 });
      this.tone({ type: 'square', freq: 72, endFreq: 38, dur: 0.09, gain: 0.12 });
      this.burst({ dur: 0.45, gain: 0.08, freq: 700, q: 0.4 });
    } else if (kind === 'shotgun') {
      this.burst({ dur: 0.32, gain: 0.65, freq: 2200, q: 0.5 });
      this.tone({ type: 'sine', freq: 110, endFreq: 32, dur: 0.3, gain: 0.8 });
      this.tone({ type: 'triangle', freq: 190, endFreq: 50, dur: 0.2, gain: 0.3 });
      this.burst({ dur: 0.7, gain: 0.12, freq: 520, q: 0.4 });
    } else if (kind === 'pistol') {
      this.burst({ dur: 0.1, gain: 0.46, freq: 4200, q: 0.8, type: 'highpass' });
      this.burst({ dur: 0.13, gain: 0.28, freq: 1700, q: 1.2, type: 'bandpass' });
      this.tone({ type: 'triangle', freq: 210, endFreq: 60, dur: 0.12, gain: 0.42 });
    } else if (kind === 'enemy') {
      this.burst({ dur: 0.12, gain: 0.15, freq: 2400, q: 3 });
      this.tone({ type: 'sawtooth', freq: 520, endFreq: 160, dur: 0.12, gain: 0.08 });
    } else if (kind === 'charge') {
      this.tone({ type: 'sawtooth', freq: 180, endFreq: 900, dur: 0.5, gain: 0.07, slide: 0.9 });
    }
  }

  dryFire() {
    if (!this.ctx) return;
    this.burst({ dur: 0.04, gain: 0.18, freq: 2600, q: 2, type: 'bandpass' });
    this.tone({ type: 'square', freq: 1200, endFreq: 400, dur: 0.03, gain: 0.04 });
  }

  reload(duration = 1.8) {
    if (!this.ctx) return;
    const beats = [0.02, duration * 0.22, duration * 0.55, duration * 0.8];
    beats.forEach((b, i) => {
      this.burst({ dur: 0.055, gain: i === 3 ? 0.24 : 0.16, freq: 1800 + i * 400, q: 2.4, type: 'bandpass', when: b });
      this.tone({ type: 'square', freq: 320 + i * 90, endFreq: 120, dur: 0.05, gain: 0.025, when: b });
    });
  }

  step(sprint = false) {
    if (!this.ctx) return;
    this.burst({ dur: 0.09, gain: sprint ? 0.2 : 0.12, freq: 380, q: 0.8 });
    this.tone({ type: 'sine', freq: 90, endFreq: 42, dur: 0.08, gain: 0.08 });
  }

  jump() {
    if (!this.ctx) return;
    this.burst({ dur: 0.12, gain: 0.1, freq: 500, q: 0.8 });
  }

  land() {
    if (!this.ctx) return;
    this.burst({ dur: 0.18, gain: 0.24, freq: 300, q: 0.6 });
    this.tone({ type: 'sine', freq: 80, endFreq: 35, dur: 0.15, gain: 0.16 });
  }

  hitmarker(headshot = false, kill = false) {
    if (!this.ctx) return;
    this.tone({ type: 'square', freq: headshot ? 1750 : 1350, endFreq: headshot ? 1300 : 980, dur: 0.045, gain: 0.06 });
    if (kill) this.tone({ type: 'sine', freq: 880, endFreq: 440, dur: 0.16, gain: 0.05, when: 0.03 });
    if (headshot) this.tone({ type: 'sine', freq: 2600, endFreq: 1900, dur: 0.09, gain: 0.035 });
  }

  impact() {
    if (!this.ctx) return;
    this.burst({ dur: 0.06, gain: 0.1, freq: 3200, q: 1.2, type: 'bandpass' });
  }

  explosion(distance = 0) {
    if (!this.ctx) return;
    const att = Math.max(0.15, 1 - distance / 60);
    this.burst({ dur: 1.1, gain: 0.6 * att, freq: 900, q: 0.6 });
    this.tone({ type: 'sine', freq: 90, endFreq: 22, dur: 0.9, gain: 0.55 * att });
    this.burst({ dur: 0.3, gain: 0.35 * att, freq: 4000, q: 0.7, type: 'highpass' });
    this.tone({ type: 'sawtooth', freq: 160, endFreq: 40, dur: 0.3, gain: 0.12 * att });
  }

  damage() {
    if (!this.ctx) return;
    this.burst({ dur: 0.25, gain: 0.3, freq: 500, q: 0.6 });
    this.tone({ type: 'sine', freq: 65, endFreq: 30, dur: 0.28, gain: 0.3 });
    this.tone({ type: 'sawtooth', freq: 240, endFreq: 90, dur: 0.15, gain: 0.04 });
  }

  heartbeat() {
    if (!this.ctx) return;
    this.tone({ type: 'sine', freq: 58, endFreq: 38, dur: 0.2, gain: 0.18 });
    this.tone({ type: 'sine', freq: 52, endFreq: 34, dur: 0.18, gain: 0.12, when: 0.2 });
  }

  pickup() {
    if (!this.ctx) return;
    [660, 880, 1180].forEach((f, i) => this.tone({ type: 'sine', freq: f, endFreq: f * 1.04, dur: 0.11, gain: 0.05, when: i * 0.05 }));
  }

  enemyAlert() {
    if (!this.ctx) return;
    this.tone({ type: 'square', freq: 420, endFreq: 720, dur: 0.09, gain: 0.03 });
    this.tone({ type: 'square', freq: 680, endFreq: 420, dur: 0.12, gain: 0.025, when: 0.09 });
  }

  waveStart(n = 1) {
    if (!this.ctx) return;
    this.tone({ type: 'sawtooth', freq: 55, endFreq: 34, dur: 1.2, gain: 0.2 });
    this.tone({ type: 'sine', freq: 110, endFreq: 55, dur: 1, gain: 0.12 });
    for (let i = 0; i < 3; i++) {
      this.tone({ type: 'square', freq: 880 - i * 80, endFreq: 420, dur: 0.2, gain: 0.03, when: 0.5 + i * 0.18 });
    }
    this.burst({ dur: 0.9, gain: 0.05, freq: 300, q: 0.5 });
  }

  waveClear() {
    if (!this.ctx) return;
    [440, 554, 659, 880].forEach((f, i) => this.tone({ type: 'triangle', freq: f, endFreq: f, dur: 0.28, gain: 0.06, when: i * 0.11 }));
  }

  victory() {
    if (!this.ctx) return;
    [220, 277, 330, 440, 554].forEach((f, i) => this.tone({ type: 'sawtooth', freq: f, endFreq: f, dur: 0.7, gain: 0.05, when: i * 0.12 }));
    this.tone({ type: 'sine', freq: 110, endFreq: 55, dur: 2, gain: 0.16 });
  }

  defeat() {
    if (!this.ctx) return;
    [220, 185, 147, 110].forEach((f, i) => this.tone({ type: 'sawtooth', freq: f, endFreq: f * 0.97, dur: 0.6, gain: 0.06, when: i * 0.18 }));
    this.tone({ type: 'sine', freq: 55, endFreq: 26, dur: 2.2, gain: 0.18 });
  }

  ui(kind = 'click') {
    if (!this.ctx) return;
    if (kind === 'hover') {
      this.tone({ type: 'sine', freq: 1200, endFreq: 1500, dur: 0.03, gain: 0.015 });
    } else if (kind === 'click') {
      this.tone({ type: 'square', freq: 740, endFreq: 520, dur: 0.05, gain: 0.03 });
      this.burst({ dur: 0.03, gain: 0.03, freq: 2600, q: 1 });
    } else if (kind === 'back') {
      this.tone({ type: 'square', freq: 420, endFreq: 260, dur: 0.07, gain: 0.03 });
    }
  }

  update(dt, state) {
    if (!this.ctx) return;
    if (state && state.heartbeat) {
      this.heartbeatTimer -= dt;
      if (this.heartbeatTimer <= 0) {
        this.heartbeat();
        this.heartbeatTimer = 0.85;
      }
    } else {
      this.heartbeatTimer = 0;
    }
  }
}

import * as THREE from 'three';
import {
  concreteTextures, floorTextures, metalTextures, crateTextures, hazardTexture,
  signTexture, glowTexture, windowTexture, softParticleTexture,
} from './textures.js';

const BOX = new THREE.BoxGeometry(1, 1, 1);
const CYL = new THREE.CylinderGeometry(1, 1, 1, 20);
const TORUS = new THREE.TorusGeometry(1, 0.035, 8, 64);

function cloneTex(t, rx = 1, ry = 1) {
  const c = t.clone();
  c.needsUpdate = true;
  c.wrapS = c.wrapT = THREE.RepeatWrapping;
  c.repeat.set(rx, ry);
  return c;
}

export class World {
  constructor(scene, renderer) {
    this.scene = scene;
    this.renderer = renderer;
    this.colliders = [];
    this.spawns = [];
    this.animated = [];
    this.rainDrops = [];
    this.portals = [];
    this.quality = 'high';
    this.time = 0;
    this._buildMaterials();
    this._buildSky();
    this._buildArena();
    this._buildStructures();
    this._buildProps();
    this._buildAtmosphere();
    this._buildPortals();
    this._buildRain();
  }

  _buildMaterials() {
    const conc = concreteTextures();
    const metal = metalTextures();
    const crate = crateTextures();
    const hazard = hazardTexture();

    this.matConcrete = new THREE.MeshStandardMaterial({
      map: cloneTex(conc.map, 2, 1), roughnessMap: cloneTex(conc.rough, 2, 1),
      bumpMap: cloneTex(conc.bump, 2, 1), bumpScale: 0.035, color: 0x9ba0a2,
      roughness: 0.94, metalness: 0.02,
    });
    this.matConcreteDark = new THREE.MeshStandardMaterial({
      map: cloneTex(conc.map, 3, 1), roughnessMap: cloneTex(conc.rough, 3, 1),
      bumpMap: cloneTex(conc.bump, 3, 1), bumpScale: 0.03, color: 0x6f7678,
      roughness: 0.9, metalness: 0.02,
    });
    this.matMetal = new THREE.MeshStandardMaterial({
      map: cloneTex(metal.map, 2, 2), roughnessMap: cloneTex(metal.rough, 2, 2),
      color: 0x8b969c, roughness: 0.62, metalness: 0.72,
    });
    this.matMetalDark = new THREE.MeshStandardMaterial({
      map: cloneTex(metal.map, 2, 2), roughnessMap: cloneTex(metal.rough, 2, 2),
      color: 0x4c555b, roughness: 0.68, metalness: 0.78,
    });
    this.matCrate = new THREE.MeshStandardMaterial({
      map: crate.map, roughness: 0.7, metalness: 0.45, color: 0xc3c9cc,
    });
    this.matHazard = new THREE.MeshStandardMaterial({
      map: hazard.map, roughness: 0.78, metalness: 0.22, color: 0xc9c9c9,
    });
    this.matBlack = new THREE.MeshStandardMaterial({ color: 0x171b1f, roughness: 0.62, metalness: 0.7 });
    this.matRubber = new THREE.MeshStandardMaterial({ color: 0x0d1013, roughness: 0.94, metalness: 0.05 });
    this.matAmber = new THREE.MeshStandardMaterial({
      color: 0x261a08, emissive: 0xffa22e, emissiveIntensity: 3.4, roughness: 0.4, metalness: 0.2,
    });
    this.matRed = new THREE.MeshStandardMaterial({
      color: 0x2a0c0a, emissive: 0xff3b24, emissiveIntensity: 3.2, roughness: 0.4, metalness: 0.1,
    });
    this.matCyan = new THREE.MeshStandardMaterial({
      color: 0x071d24, emissive: 0x54e6ff, emissiveIntensity: 3.8, roughness: 0.35, metalness: 0.2,
    });
    this.matGlass = new THREE.MeshPhysicalMaterial({
      color: 0x0e222c, roughness: 0.08, metalness: 0.1, transmission: 0.5,
      transparent: true, opacity: 0.6, envMapIntensity: 1.4,
    });
    this.matPuddle = new THREE.MeshPhysicalMaterial({
      color: 0x141c22, roughness: 0.03, metalness: 0.55, envMapIntensity: 2.4,
      transparent: true, opacity: 0.74, clearcoat: 1, clearcoatRoughness: 0.02,
      polygonOffset: true, polygonOffsetFactor: -2,
    });
    this.matFloor = new THREE.MeshStandardMaterial({
      map: floorTextures().map, roughnessMap: floorTextures().rough,
      color: 0x9aa0a3, roughness: 0.62, metalness: 0.22,
    });
  }

  _buildSky() {
    const scene = this.scene;
    scene.fog = new THREE.FogExp2(0x080f16, 0.017);
    scene.background = new THREE.Color(0x050a10);

    const skyGeo = new THREE.SphereGeometry(260, 32, 20);
    const skyMat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        top: { value: new THREE.Color(0x02060b) },
        mid: { value: new THREE.Color(0x0b1a28) },
        bottom: { value: new THREE.Color(0x23323c) },
        moonDir: { value: new THREE.Vector3(-0.55, 0.45, -0.7).normalize() },
      },
      vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `varying vec3 vDir; uniform vec3 top; uniform vec3 mid; uniform vec3 bottom; uniform vec3 moonDir;
        void main(){
          float h = clamp(vDir.y*0.5+0.5, 0.0, 1.0);
          vec3 col = mix(bottom, mid, smoothstep(0.42,0.62,h));
          col = mix(col, top, smoothstep(0.6,0.95,h));
          float moon = pow(max(dot(normalize(vDir), moonDir), 0.0), 220.0);
          col += vec3(0.7,0.78,0.9) * moon * 1.5;
          float haze = pow(1.0-abs(vDir.y), 7.0);
          col += vec3(0.16,0.19,0.18) * haze * 0.4;
          gl_FragColor = vec4(col,1.0);
        }`,
    });
    scene.add(new THREE.Mesh(skyGeo, skyMat));

    // stars
    const starCount = 900;
    const pos = new Float32Array(starCount * 3);
    for (let i = 0; i < starCount; i++) {
      const a = Math.random() * Math.PI * 2;
      const y = Math.random() * 0.62 + 0.18;
      const r = Math.sqrt(1 - y * y);
      pos[i * 3] = Math.cos(a) * r * 240;
      pos[i * 3 + 1] = y * 240;
      pos[i * 3 + 2] = Math.sin(a) * r * 240;
    }
    const starGeo = new THREE.BufferGeometry();
    starGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({
      color: 0xbcd2e6, size: 1.4, sizeAttenuation: false, transparent: true, opacity: 0.55, fog: false,
    }));
    scene.add(stars);

    // moon glow sprite
    const moonTex = glowTexture('rgba(180,205,235,1)');
    const moon = new THREE.Sprite(new THREE.SpriteMaterial({
      map: moonTex, color: 0xdde8ff, transparent: true, depthWrite: false,
      blending: THREE.AdditiveBlending, opacity: 0.9, fog: false,
    }));
    moon.position.set(-95, 82, -125);
    moon.scale.set(34, 34, 1);
    scene.add(moon);
    const moonCore = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('rgba(240,248,255,1)'), color: 0xffffff, transparent: true,
      depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0.9, fog: false,
    }));
    moonCore.position.copy(moon.position).add(new THREE.Vector3(0, 0, 1));
    moonCore.scale.set(9, 9, 1);
    scene.add(moonCore);

    // distant city silhouette
    const city = new THREE.Group();
    const win = windowTexture(2);
    for (let i = 0; i < 42; i++) {
      const a = (i / 42) * Math.PI * 2 + Math.random() * 0.1;
      const rad = 92 + Math.random() * 48;
      const h = 9 + Math.random() * 36;
      const w = 6 + Math.random() * 12;
      const b = new THREE.Mesh(BOX, new THREE.MeshStandardMaterial({
        color: 0x0b1218, roughness: 0.9, metalness: 0.2,
        map: cloneTex(win, Math.max(1, w / 5), Math.max(1, h / 8)),
        emissiveMap: cloneTex(win, Math.max(1, w / 5), Math.max(1, h / 8)),
        emissive: 0x8fa4b4, emissiveIntensity: 0.5,
      }));
      b.position.set(Math.cos(a) * rad, h / 2, Math.sin(a) * rad);
      b.scale.set(w, h, w);
      b.rotation.y = -a;
      city.add(b);
      if (Math.random() < 0.6) {
        const beacon = new THREE.Sprite(new THREE.SpriteMaterial({
          map: glowTexture('rgba(255,70,50,1)'), color: 0xff4a32, transparent: true,
          depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0.9, fog: false,
        }));
        beacon.position.set(b.position.x, h + 1.5, b.position.z);
        beacon.scale.set(3, 3, 1);
        city.add(beacon);
      }
    }
    scene.add(city);

    // lighting
    const hemi = new THREE.HemisphereLight(0x7294b5, 0x17120d, 0.55);
    scene.add(hemi);
    const moonLight = new THREE.DirectionalLight(0xa8c4e8, 1.75);
    moonLight.position.set(-32, 46, -40);
    moonLight.castShadow = true;
    moonLight.shadow.mapSize.set(2048, 2048);
    moonLight.shadow.camera.left = -42;
    moonLight.shadow.camera.right = 42;
    moonLight.shadow.camera.top = 42;
    moonLight.shadow.camera.bottom = -42;
    moonLight.shadow.camera.near = 1;
    moonLight.shadow.camera.far = 130;
    moonLight.shadow.bias = -0.0008;
    moonLight.shadow.normalBias = 0.03;
    scene.add(moonLight);
    this.moonLight = moonLight;
  }

  _buildArena() {
    const floor = new THREE.Mesh(new THREE.PlaneGeometry(64, 64), this.matFloor);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    this.scene.add(floor);
    this.floor = floor;

    // outer walls
    const wallH = 9;
    const wallSpecs = [
      [0, -32.4, 66, wallH, 1.0],
      [0, 32.4, 66, wallH, 1.0],
      [-32.4, 0, 1.0, wallH, 66],
      [32.4, 0, 1.0, wallH, 66],
    ];
    for (const [x, z, w, h, d] of wallSpecs) {
      const wall = new THREE.Mesh(BOX, this.matConcreteDark);
      wall.position.set(x, h / 2, z);
      wall.scale.set(w, h, d);
      wall.receiveShadow = true;
      wall.castShadow = true;
      this.scene.add(wall);
      this.addCollider(x - w / 2, z - d / 2, x + w / 2, z + d / 2, 0, h);
    }

    // wall panel ribs + upper trim
    for (let i = -30; i <= 30; i += 6) {
      for (const side of [-1, 1]) {
        const ribZ = new THREE.Mesh(BOX, this.matMetalDark);
        ribZ.position.set(i, 4.5, side * 31.7);
        ribZ.scale.set(0.28, 9, 0.5);
        ribZ.castShadow = true;
        this.scene.add(ribZ);
        const ribX = new THREE.Mesh(BOX, this.matMetalDark);
        ribX.position.set(side * 31.7, 4.5, i);
        ribX.scale.set(0.5, 9, 0.28);
        ribX.castShadow = true;
        this.scene.add(ribX);
      }
    }
    // lower hazard skirting
    for (const [x, z, w, d] of [[0, -31.86, 64, 0.12], [0, 31.86, 64, 0.12], [-31.86, 0, 0.12, 64], [31.86, 0, 0.12, 64]]) {
      const strip = new THREE.Mesh(BOX, this.matHazard);
      strip.position.set(x, 0.45, z);
      strip.scale.set(w, 0.9, d);
      this.scene.add(strip);
    }
    // catwalk rim
    for (const side of [-1, 1]) {
      const walk = new THREE.Mesh(BOX, this.matMetalDark);
      walk.position.set(0, 5.3, side * 30.7);
      walk.scale.set(64, 0.2, 2.4);
      walk.castShadow = true;
      this.scene.add(walk);
      const walkX = new THREE.Mesh(BOX, this.matMetalDark);
      walkX.position.set(side * 30.7, 5.3, 0);
      walkX.scale.set(2.4, 0.2, 64);
      walkX.castShadow = true;
      this.scene.add(walkX);
    }
    // railing posts
    for (let i = -30; i <= 30; i += 4) {
      for (const side of [-1, 1]) {
        const postZ = new THREE.Mesh(BOX, this.matMetal);
        postZ.position.set(i, 6.05, side * 29.6);
        postZ.scale.set(0.09, 1.5, 0.09);
        this.scene.add(postZ);
        const postX = new THREE.Mesh(BOX, this.matMetal);
        postX.position.set(side * 29.6, 6.05, i);
        postX.scale.set(0.09, 1.5, 0.09);
        this.scene.add(postX);
      }
    }
    for (const [x, z, w, d] of [[0, 29.6, 61, 0.06], [0, -29.6, 61, 0.06], [29.6, 0, 0.06, 61], [-29.6, 0, 0.06, 61]]) {
      const rail = new THREE.Mesh(BOX, this.matMetal);
      rail.position.set(x, 6.7, z);
      rail.scale.set(w, 0.07, d);
      this.scene.add(rail);
    }

    // subtle floor light strips
    this.floorLights = [];
    for (const [x, z, w, d] of [
      [-20, 12, 5, 0.12], [20, 12, 5, 0.12],
      [-10, -19, 0.12, 5], [10, -19, 0.12, 5],
      [-20, -6, 4, 0.1], [20, -6, 4, 0.1],
    ]) {
      const strip = new THREE.Mesh(BOX, this.matAmber.clone());
      strip.material.emissiveIntensity = 1.4;
      strip.position.set(x, 0.025, z);
      strip.scale.set(w, 0.03, d);
      this.scene.add(strip);
      this.floorLights.push(strip);
    }

    // puddles
    for (let i = 0; i < 16; i++) {
      const r = 0.8 + Math.random() * 2.6;
      const puddle = new THREE.Mesh(new THREE.CircleGeometry(r, 24), this.matPuddle);
      puddle.rotation.x = -Math.PI / 2;
      puddle.rotation.z = Math.random() * Math.PI;
      puddle.scale.y = 0.4 + Math.random() * 0.7;
      puddle.position.set((Math.random() - 0.5) * 54, 0.012, (Math.random() - 0.5) * 54);
      this.scene.add(puddle);
    }

    // painted floor decals
    const decal = (text, x, z, w, h, rot = 0, accent = '#c69a3e') => {
      const mesh = new THREE.Mesh(
        new THREE.PlaneGeometry(w, h),
        new THREE.MeshStandardMaterial({
          map: signTexture(text, '', accent), transparent: false, roughness: 0.7,
          metalness: 0.1, polygonOffset: true, polygonOffsetFactor: -1,
        }),
      );
      mesh.rotation.x = -Math.PI / 2;
      mesh.rotation.z = rot;
      mesh.position.set(x, 0.02, z);
      this.scene.add(mesh);
    };
    decal('CAUTION', -13, 13, 5, 1.25, 0.04);
    decal('SECTOR 07', 14, -12, 5.6, 1.25, Math.PI + 0.04);
    decal('AUTHORIZED', -14, -13, 5.6, 1.25, -0.03, '#9fb6c4');
  }

  _buildStructures() {
    // central reactor plinth
    const plinth = new THREE.Mesh(new THREE.CylinderGeometry(4.4, 4.9, 1.2, 8), this.matConcreteDark);
    plinth.position.set(0, 0.6, -1);
    plinth.castShadow = true; plinth.receiveShadow = true;
    this.scene.add(plinth);
    this.addCollider(-4.9, -5.9, 4.9, 3.9, 0, 1.2);
    const ring = new THREE.Mesh(new THREE.TorusGeometry(4.25, 0.09, 8, 64), this.matAmber);
    ring.rotation.x = Math.PI / 2;
    ring.position.set(0, 1.22, -1);
    this.scene.add(ring);
    const cap = new THREE.Mesh(new THREE.CylinderGeometry(3.4, 3.9, 0.5, 8), this.matMetalDark);
    cap.position.set(0, 1.45, -1);
    this.scene.add(cap);
    this.holo = new THREE.Group();
    this.holo.position.set(0, 3.1, -1);
    const core = new THREE.Mesh(new THREE.IcosahedronGeometry(1.15, 1), new THREE.MeshBasicMaterial({
      color: 0x55e4ff, wireframe: true, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending,
    }));
    this.holo.add(core);
    const coreGlow = new THREE.Mesh(new THREE.IcosahedronGeometry(0.75, 1), new THREE.MeshBasicMaterial({
      color: 0x2fc8e6, wireframe: true, transparent: true, opacity: 0.85,
    }));
    coreGlow.scale.setScalar(0.62);
    this.holo.add(coreGlow);
    this.holoCore = core;
    this.holoCoreGlow = coreGlow;
    const ring2 = new THREE.Mesh(TORUS, new THREE.MeshBasicMaterial({
      color: 0x6ee9ff, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending,
    }));
    ring2.scale.setScalar(2.2);
    ring2.rotation.x = 1.2;
    this.holo.add(ring2);
    const ring3 = new THREE.Mesh(TORUS, new THREE.MeshBasicMaterial({
      color: 0x6ee9ff, transparent: true, opacity: 0.35, blending: THREE.AdditiveBlending,
    }));
    ring3.scale.setScalar(2.8);
    ring3.rotation.x = 2.1; ring3.rotation.y = 0.5;
    this.holo.add(ring3);
    this.holoRing2 = ring2;
    this.holoRing3 = ring3;
    const projector = new THREE.PointLight(0x54e6ff, 16, 16, 1.7);
    projector.position.set(0, 2.4, -1);
    this.scene.add(projector);
    this.projector = projector;
    this.scene.add(this.holo);

    // 4 corner sentinel pillars
